package study
import"testing"
func TestScoreRequiresPinnedBalancedPassingPairs(t *testing.T){task:=Task{ID:"t",Model:"m",Tools:[]string{"tool"},Limit:10,Oracle:"o"};m:=Manifest{SchemaVersion:"1.0.0",StudyID:"s",Repository:"o/r",Revision:"rev",MinimumPairs:1,Tasks:[]Task{task}};out:=func(arm,status string)Outcome{return Outcome{Repository:"o/r",Revision:"rev",RunID:"run",ArtifactDigest:"digest",StartedAt:"start",FinishedAt:"finish",TaskID:"t",Arm:arm,Model:"m",Tools:[]string{"tool"},Limit:10,Oracle:"o",Status:status}};report,err:=Score(m,Results{SchemaVersion:"1.0.0",StudyID:"s",Outcomes:[]Outcome{out("control","PASS"),out("workflow","PASS")}});if err!=nil||!report.ClaimAllowed{t.Fatal(err)};report,_=Score(m,Results{SchemaVersion:"1.0.0",StudyID:"s",Outcomes:[]Outcome{out("control","PASS"),out("workflow","TIMEOUT")}});if report.ClaimAllowed{t.Fatal("timeout must block claim")}}
func TestScoreRejectsUnpinnedOutcome(t *testing.T){m:=Manifest{SchemaVersion:"1.0.0",StudyID:"s",MinimumPairs:1,Tasks:[]Task{{ID:"t",Model:"m",Tools:[]string{"x"},Limit:1,Oracle:"o"}}};_,err:=Score(m,Results{SchemaVersion:"1.0.0",StudyID:"s",Outcomes:[]Outcome{{TaskID:"t",Arm:"control",Model:"other",Tools:[]string{"x"},Limit:1,Oracle:"o",Status:"PASS"}}});if err==nil{t.Fatal("expected pin mismatch")}}
func TestScoreRejectsNegativeFalsePositives(t *testing.T){m:=Manifest{SchemaVersion:"1.0.0",StudyID:"s",Repository:"o/r",Revision:"rev",MinimumPairs:1,Tasks:[]Task{{ID:"t",Model:"m",Tools:[]string{"x"},Limit:1,Oracle:"o"}}};o:=Outcome{Repository:"o/r",Revision:"rev",RunID:"run",ArtifactDigest:"d",StartedAt:"s",FinishedAt:"f",TaskID:"t",Arm:"control",Model:"m",Tools:[]string{"x"},Limit:1,Oracle:"o",Status:"PASS",FalsePositives:-1};if _,err:=Score(m,Results{SchemaVersion:"1.0.0",StudyID:"s",Outcomes:[]Outcome{o}});err==nil{t.Fatal("expected negative rejection")}}
